import { Component, Input, OnDestroy, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import * as moment from 'moment';
import { LiraPipe } from '../../core/pipes/lira.pipe';
import { DollarPipe } from '../../core/pipes/dollar.pipe';
import { ExchangedLiraPipe } from '../../core/pipes/exchanged-lira.pipe';
import { InvoiceItems } from '../../core/interfaces/customer.interface';
import { PrintService } from 'src/app/print.service';
import { Subscription } from 'rxjs';

@Component({
    selector: 'app-print',
    standalone: true,
    imports: [CommonModule],
    templateUrl: './print.component.html',
    styleUrls: ['./print.component.scss'],
})
export class PrintComponent implements OnInit, OnDestroy {
    constructor(private printService: PrintService) {}

    subscriptions = new Subscription();
    invoice;
    fixedHeader: boolean;
    moment = moment;

    ngOnInit(): void {
        this.subscriptions.add(
            this.printService.invoice.subscribe((res) => {
                this.invoice = res;
            })
        );
    }

    ngOnDestroy(): void {
        this.subscriptions.unsubscribe();
    }

    // Function to split the array into chunks of 10 items each
    splitArrayIntoChunks(
        array: InvoiceItems[],
        chunkSize: number
    ): InvoiceItems[][] {
        if (!this.fixedHeader) return [this.invoice.invoice_map];
        const chunks = [];
        for (let i = 0; i < array.length; i += chunkSize) {
            chunks.push(array.slice(i, i + chunkSize));
        }

        return chunks;
    }
}
